-- Запись журнала обновлений (ADR 0077): выпуск 83 — год в дате талона перестал быть догадкой
-- модели (ADR 0166, план `docs/waste-ticket-date-escalation-plan.md`, этапы Э1–Э4).
--
-- ОТКУДА НОМЕР. `ls apps/api/drizzle` перед созданием файла (07.09.2026): последней в дереве
-- стоит `0281_releases_fix_quick_status_version.sql` соседнего потока — она появилась и уехала
-- коммитом, пока шла эта волна, и заняла номер, свободный часом раньше. Свободен 0282, он и взят.
-- Парная миграция этой волны — `0280_waste_tickets_issued_on_raw.sql` (колонка написания даты).
--
-- `seq = 83`, И ЭТО ПЕРВЫЙ НЕЗАНЯТЫЙ. Номер спрошен у РЕПОЗИТОРИЯ
-- (`grep -h "^  [0-9]\+, '" apps/api/drizzle/*releases*.sql`), а не у базы: на technic_dev часть
-- закоммиченных выпусков просто не накатана, и `max(seq)` там врёт в меньшую сторону. Лента идёт
-- без дыр до 82 (`0.1.71.0164` после правки версии соседним потоком). Версия `0.1.72.0166`:
-- счётчик идёт дальше от 71, хвост — номер решения.
--
-- ЧТО ЭТА ЗАПИСЬ ОБЕЩАЕТ И ЧЕГО НЕ ОБЕЩАЕТ. Обещано меньше ошибок в ГОДУ даты талона и один клик
-- на исправление там, где ошибка всё же случилась. Не обещано, что дата теперь всегда верна:
-- расхождение в год вместе со сдвигом дня или месяца безопасной подсказки не даёт и остаётся
-- обычным предупреждением, а «доля правок даты» в отчётах качества (ADR 0137) после этого выпуска
-- сравнима с прежней только с отметкой о смене методики — исправление по подсказке тоже правка,
-- и совершить его стало заметно проще.
--
-- ОБРАТИМОСТЬ: строка ленты, `DELETE FROM app_releases WHERE seq = 83`.

INSERT INTO app_releases (seq, version, released_on, title, adrs, items) VALUES (
  83, '0.1.72.0166', '2026-09-07', 'Талоны вывоза: год в дате выбирает портал, а не модель', '{166}',
  '[
    {"kind":"fix","text":"Год в дате талона больше не выдумывается моделью. Раньше в задании стоял пример «25 → 2025», а какой сейчас год, модель не знала вовсе — отсюда и брались предупреждения «расхождение 351 день». Теперь модель возвращает то, что написано в графе, а век двузначной записи выбирает портал по дате заявки: ближайший к ней год"},
    {"kind":"feature","text":"Замечание о расхождении даты предлагает исправление одним нажатием. Если замена только года приводит дату талона к дате вывоза, портал так и пишет — «вероятно, неверно распознан год» — и рядом ставит кнопку «Исправить год». Нажатие правит талон обычным путём, с журналом и правами; если за это время подсказка изменилась или расхождение уже приняли, портал скажет об этом и обновит карточку"},
    {"kind":"feature","text":"Под датой талона видно, что модель прочитала в графе: «OCR в графе: 17.08.25». Сверяя талон с бумагой, теперь видно и написание, и то, что из него получилось. У талонов, заведённых руками, и у прочитанных до этого выпуска подписи нет — написание у них не спрашивали"},
    {"kind":"improvement","text":"Дата, далеко отстоящая от даты заявки, перечитывается второй моделью — как и дата, противоречащая собственному написанию. Раньше второй проход запускался, только если поле осталось пустым, и уверенно прочитанная неверная дата проходила разбор без остановки"},
    {"kind":"fix","text":"Страница, уже прочитанная двумя моделями, при повторном разборе больше не теряет вторую: её ответ берётся из кэша наравне со свежим. Заодно расход перестал занижаться — страница считается прочитанной без обращения к модели, только если наружу не ходили ни разу, включая неудачный второй проход"},
    {"kind":"improvement","text":"Если дату вывоза или плановую дату заявки поправили, пока шло распознавание, портал пересчитывает прочитанное по новой дате и записывает результат сразу. Ждать и звать модель заново приходится, только если новой дате нужен второй проход, которого ещё не делали"}
  ]'::jsonb
);
